/**
 * Fit: scales an object so it fits the screen, following resizes.
 *
 * Generated by Pixi Editor (components v1). Plain TypeScript: safe to read, edit and commit.
 */
import { Component, getScreen } from "../core";

export type FitMode = "contain" | "cover";

export interface FitParams {
  /** contain = fit fully inside the screen; cover = fill it, cropping the overflow. */
  mode: FitMode;
  /** Empty space to leave around the object, in pixels. */
  padding: number;
}

/** Scales the object uniformly so its natural size fits the screen, even when it resizes. */
export class Fit extends Component<FitParams> {
  static readonly componentName = "Fit";
  static readonly defaults: FitParams = { mode: "contain", padding: 0 };

  private baseWidth = 0;
  private baseHeight = 0;

  attach(): void {
    this.measure();
  }

  update(): void {
    this.apply();
  }

  apply(): void {
    const screen = getScreen();
    if (!screen) return;
    if (this.baseWidth <= 0 || this.baseHeight <= 0) this.measure();
    if (this.baseWidth <= 0 || this.baseHeight <= 0) return;
    const availW = Math.max(0, screen.width - this.params.padding * 2);
    const availH = Math.max(0, screen.height - this.params.padding * 2);
    const sx = availW / this.baseWidth;
    const sy = availH / this.baseHeight;
    const k =
      this.params.mode === "cover" ? Math.max(sx, sy) : Math.min(sx, sy);
    if (Number.isFinite(k) && k > 0) this.target.scale.set(k);
  }

  /** Remembers the object's unscaled size so the fit factor can be recomputed any time. */
  private measure(): void {
    const bounds = this.target.getLocalBounds();
    this.baseWidth = bounds.width;
    this.baseHeight = bounds.height;
  }
}
